    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Adaptive Best-Fit: Prefer smaller post_residuals, but apply a non-linear 
    // penalty to residuals that are too small to be useful for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Strong penalty for creating a "dead" space that cannot fit the next item
            score += 45.0 + (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that maintain a "buffer" for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 2. Fragment Avoidance: Targeted penalty for "micro-fragments" (1-8).
    // These are statistically the hardest to fill in 100-capacity bins.
    if post_residual > 0 && post_residual < 9 {
        score += 30.0;
    }

    // 3. Dynamic Bin Opening Logic: 
    // Discourage opening new bins unless the current options are significantly inefficient.
    if bin_residual == bin_capacity {
        // As the stream progresses, make it harder to open new bins to force compaction.
        score += 30.0 + (progress * 40.0);
        // If there are other bins available, make opening a new one very expensive.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Mean Residual Feedback: If mean_residual is high, we are wasting space.
    // Tighten the scoring to favor Best-Fit more aggressively.
    if mean_residual > 25.0 {
        score += post_residual as f64 * 0.8;
    } else {
        score -= post_residual as f64 * 0.2;
    }

    // 5. Critical Constraint: If only one bin fits, prioritize it to avoid opening new ones.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Multi-bin penalty: If we have too many open bins, penalize the score of 
    // existing bins to force them to close faster.
    if open_bins_count > 10 {
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

