pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Dynamic New Bin Thresholding
    // Discourage opening bins unless necessary, scaling by remaining stream length
    if is_new_bin {
        let open_bin_penalty = (open_bins_count as f64).powf(1.1) * 8.0;
        score += 85.0 + (progress * 40.0) + open_bin_penalty;
        if fitting_bins_count > 0 {
            score += 300.0;
        }
    }

    // 2. Lookahead & Fragmentation Control
    // Prioritize bins that can hold the next item (synergy)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0; // Reward bin capacity for next item
            if post_residual == next_item_size { score -= 40.0; } // Perfect fit bonus
            else if post_residual < 20 { score -= 10.0; }
        } else if post_residual > 0 && post_residual < 18 {
            // Penalize "dead zones" that are too small for most items
            score += 55.0;
        }
    }

    // 3. Utilization & Finalization
    // Prioritize bins nearing full capacity to clear them from active status
    if !is_new_bin {
        let usage = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= usage * 50.0;
        if post_residual < 12 {
            score -= 25.0;
        }
    }

    // 4. Variance and Distribution Alignment
    // Align residuals with common item sizes (factors of 25 and 20)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.35;

    let rem25 = post_residual % 25;
    if rem25 == 0 { score -= 15.0; }
    else if rem25 > 20 { score -= 8.0; }
    else { score += rem25 as f64 * 0.4; }

    // 5. Critical Path Handling
    // If this is the only bin that can hold this item, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 200.0;
    }

    // 6. Terminal Phase Aggression
    // In the last 10% of the stream, prioritize maximizing bin occupation
    if progress > 0.90 {
        score -= (bin_capacity - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common divisors 
    // or next_item_size, effectively favoring residuals that can accommodate upcoming items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0 + (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that are "near-perfect" fits for the next item
            score -= (post_residual % next_item_size) as f64 * 0.5;
        }
    }

    // 2. Fragment Avoidance: Penalize residuals that create "dead zones" (e.g., < 10) 
    // which are statistically unlikely to be filled by the item distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Bin Efficiency: Favor bins that are already partially filled to pack them tighter,
    // unless this is the last chance bin (fitting_bins_count == 1).
    if fitting_bins_count > 1 {
        let usage = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= usage * 10.0;
    }

    // 4. Global Load Balancing: If we are deep into the stream, penalize opening new bins
    // unless the current residual is significantly suboptimal.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 20.0);
    }

    // 5. Harmonic Class Coupling: Penalize residuals that are non-multiples of 20 
    // (targeting 100/5 = 20 as a stable packing unit).
    if post_residual % 20 != 0 {
        score += (post_residual % 20) as f64 * 0.25;
    }

    score
}
